1	/**
2	 * 技能→系统加成映射 — 技能影响多系统（吃饭/旅行/工作/银行/职场等）
3	 *
4	 * 设计理念：每项技能不仅解锁工作，还对相关的游戏系统产生渐进式加成，
5	 * 让技能培养有持续正反馈，形成"学以致用"的良性循环。
6	 */
7	
8	/** cooking技能 → 自己做饭折扣（技能越高做饭越划算） */
9	function getCookingDiscount(cookingLevel) {
10	  // 自己做饭花费 = 基础花费 * (1 - cookingLevel * 0.008)
11	  // level 0: 全额, level 50: 6折, level 100: 2折（最低保底3折）
12	  return Math.min(0.7, cookingLevel * 0.008);
13	}
14	
15	/** driving技能 → 旅行AP减免 */
16	function getTravelApReduction(drivingLevel) {
17	  // 每20级减1AP，最多减5AP
18	  return Math.min(5, Math.floor(drivingLevel / 20));
19	}
20	
21	/** english技能 → 家教额外收入加成 */
22	function getTutoringBonus(englishLevel) {
23	  return englishLevel * 0.3;
24	}
25	
26	/** accounting技能 → 银行利率加成 */
27	function getBankRateBonus(accountingLevel) {
28	  // 每年最多+5%（日息约+0.00014），100级满分
29	  return accountingLevel * 0.0005;
30	}
31	
32	/** electrician技能 → 工厂类工作收入加成百分比 */
33	function getFactoryBonus(electricianLevel) {
34	  return electricianLevel * 0.005;
35	}
36	
37	/** welding技能 → 建筑类工作收入加成百分比 */
38	function getConstructionBonus(weldingLevel) {
39	  return weldingLevel * 0.008;
40	}
41	
42	/** coding技能 → 职场能力加成（每10级+2点ability） */
43	function getCorpAbilityBonus(codingLevel) {
44	  return Math.floor(codingLevel / 10) * 2;
45	}
46	
47	/** management技能 → 职场向上管理加成（每10级+1点upwardMgmt） */
48	function getCorpUpwardBonus(managementLevel) {
49	  return Math.floor(managementLevel / 10) * 1;
50	}
51	
52	/** repair技能 → 装备/工具效果加成（百分比） */
53	function getRepairBonus(repairLevel) {
54	  return repairLevel * 0.005;
55	}
56	
57	/** sales技能 → 交易买卖价格优势 */
58	function getSalesTradeDiscount(salesLevel) {
59	  // 买入折扣：最高15%
60	  return Math.min(0.15, salesLevel * 0.002);
61	}
62	function getSalesTradePremium(salesLevel) {
63	  // 卖出溢价：最高15%
64	  return Math.min(0.15, salesLevel * 0.002);
65	}
66	
67	// ====== P2#12 技能树分支感知加成（调用原函数 + 叠加分支加成） ======
68	
69	/**
70	 * 获取厨艺打折 + 分支加成（家常大厨额外减食材成本）
71	 */
72	function getBranchCookingDiscount(state) {
73	  var base = getCookingDiscount(
74	    (state.skills.cooking && state.skills.cooking.level) || 0,
75	  );
76	  if (!state.skillBranches || state.skillBranches.cooking !== "home_chef")
77	    return base;
78	  var reduction = 0.15; // 家常大厨基础成本减免
79	  if (typeof getTalentNodeEffects === "function") {
80	    var eff = getTalentNodeEffects(state);
81	    reduction += eff.foodCostReduction || 0;
82	  }
83	  return Math.min(0.8, base + reduction);
84	}
85	
86	/**
87	 * 获取旅行AP减免 + 分支加成（客运驾驶额外减免）
88	 */
89	function getBranchTravelApReduction(state) {
90	  var base = getTravelApReduction(
91	    (state.skills.driving && state.skills.driving.level) || 0,
92	  );
93	  if (
94	    !state.skillBranches ||
95	    state.skillBranches.driving !== "passenger_transport"
96	  )
97	    return base;
98	  if (typeof getTalentNodeEffects === "function") {
99	    var eff = getTalentNodeEffects(state);
100	    return base + (eff.extraApReduction || 2);
101	  }
102	  return base + 1;
103	}
104	
105	/**
106	 * 获取家教加成 + 分支加成（商务英语额外+50%）
107	 */
108	function getBranchTutoringBonus(state) {
109	  var base = getTutoringBonus(
110	    (state.skills.english && state.skills.english.level) || 0,
111	  );
112	  if (
113	    !state.skillBranches ||
114	    state.skillBranches.english !== "business_english"
115	  )
116	    return base;
117	  return base * 1.5;
118	}
119	
120	/**
121	 * 获取工厂加成 + 分支加成（强电工程翻倍）
122	 */
123	function getBranchFactoryBonus(state) {
124	  var base = getFactoryBonus(
125	    (state.skills.electrician && state.skills.electrician.level) || 0,
126	  );
127	  if (
128	    !state.skillBranches ||
129	    state.skillBranches.electrician !== "industrial_electric"
130	  )
131	    return base;
132	  return base * 2.0;
133	}
134	
135	/**
136	 * 获取建筑加成 + 分支加成（结构焊接+50%）
137	 */
138	function getBranchConstructionBonus(state) {
139	  var base = getConstructionBonus(
140	    (state.skills.welding && state.skills.welding.level) || 0,
141	  );
142	  if (
143	    !state.skillBranches ||
144	    state.skillBranches.welding !== "structural_welding"
145	  )
146	    return base;
147	  return base * 1.5;
148	}
149	
150	/**
151	 * 获取买入折扣 + 分支加成（门店销售上限提升到25%）
152	 */
153	function getBranchSalesDiscount(state) {
154	  var base = getSalesTradeDiscount(
155	    (state.skills.sales && state.skills.sales.level) || 0,
156	  );
157	  if (!state.skillBranches || state.skillBranches.sales !== "store_sales")
158	    return base;
159	  var extra = 0;
160	  if (typeof getTalentNodeEffects === "function") {
161	    extra = getTalentNodeEffects(state).extraDiscount || 0;
162	  }
163	  return Math.min(0.25, base + 0.1 + extra);
164	}
165	
166	/**
167	 * 获取卖出溢价 + 分支加成（商务谈判上限提升到25%）
168	 */
169	function getBranchSalesPremium(state) {
170	  var base = getSalesTradePremium(
171	    (state.skills.sales && state.skills.sales.level) || 0,
172	  );
173	  if (!state.skillBranches || state.skillBranches.sales !== "biz_negotiation")
174	    return base;
175	  var extra = 0;
176	  if (typeof getTalentNodeEffects === "function") {
177	    extra = getTalentNodeEffects(state).extraPremium || 0;
178	  }
179	  return Math.min(0.25, base + 0.1 + extra);
180	}
