315	function _mulCityPulseMap(target, source) {
316	  if (!source) return;
317	  for (var key in source) {
318	    target[key] = (target[key] || 1) * source[key];
319	  }
320	}
321	
322	function getCityPulse(state) {
323	  var pulse = {
324	    footfall: {},
325	    jobs: {},
326	    labels: [],
327	    tips: [],
328	    rules: [],
329	  };
330	  var activeNews = (state && state.activeNews) || [];
331	  for (var i = 0; i < activeNews.length; i++) {
332	    var news = activeNews[i] || {};
333	    var text = (news.id || "") + " " + (news.headline || "");
334	    for (var r = 0; r < CITY_PULSE_RULES.length; r++) {
335	      var rule = CITY_PULSE_RULES[r];
336	      if (!rule.test.test(text)) continue;
337	      _mulCityPulseMap(pulse.footfall, rule.footfall);
338	      _mulCityPulseMap(pulse.jobs, rule.jobs);
339	      if (pulse.labels.indexOf(rule.label) === -1)
340	        pulse.labels.push(rule.label);
341	      if (rule.tip && pulse.tips.indexOf(rule.tip) === -1)
342	        pulse.tips.push(rule.tip);
343	      pulse.rules.push(rule);
344	    }
345	  }
346	  return pulse;
347	}
348	
349	function getNewsJobMultiplier(jobId, state) {
350	  var pulse = getCityPulse(state);
351	  return pulse.jobs[jobId] || 1.0;
352	}
353	
354	function getNewsJobMultiplierDesc(jobId, state) {
355	  var pulse = getCityPulse(state);
356	  var hits = [];
357	  for (var i = 0; i < pulse.rules.length; i++) {
358	    var rule = pulse.rules[i];
359	    if (rule.jobs && rule.jobs[jobId] && rule.jobs[jobId] !== 1) {
360	      var pct = Math.round((rule.jobs[jobId] - 1) * 100);
361	      hits.push(rule.label + (pct > 0 ? "+" : "") + pct + "%");
362	    }
363	  }
364	  return hits.length ? hits.join("，") : "";
365	}
366	
367	function getLocationNewsBadges(locKey, state) {
368	  var pulse = getCityPulse(state);
369	  var badges = [];
370	  for (var i = 0; i < pulse.rules.length; i++) {
371	    var rule = pulse.rules[i];
372	    if (rule.footfall && rule.footfall[locKey]) {
373	      var pct = Math.round((rule.footfall[locKey] - 1) * 100);
374	      badges.push({
375	        label: rule.label + (pct > 0 ? "+" : "") + pct + "%",
376	        positive: pct >= 0,
377	        tip: rule.tip || "",
378	      });
379	    }
380	  }
381	  return badges;
382	}
383	
384	function getCityPulseTips(state, limit) {
385	  var tips = getCityPulse(state).tips;
386	  return typeof limit === "number" ? tips.slice(0, limit) : tips;
387	}
388	
389	/**
390	 * 工作后分发技能经验值（与工作类型关联）
391	 * 返回字符串描述获得了什么XP
392	 */
393	function grantJobSkillXp(jobId, state) {
394	  var job =
395	    typeof STREET_JOBS !== "undefined"
396	      ? STREET_JOBS.find(function (j) {
397	          return j.id === jobId;
398	        })
399	      : null;
400	  if (!job) return "";
401	
402	  var xpMap = {
403	    // 烹饪相关工作 → cooking XP
404	    street_vending_food: { skill: "cooking", min: 2, max: 5 },
405	    food_stall: { skill: "cooking", min: 3, max: 7 },
406	    // 销售相关工作 → sales XP
407	    street_vending_goods: { skill: "sales", min: 2, max: 5 },
408	    barber: { skill: "sales", min: 2, max: 4 },
409	    // 维修相关工作 → repair XP
410	    skilled_labor_construction: { skill: "repair", min: 3, max: 6 },
411	    repair_service: { skill: "repair", min: 4, max: 8 },
412	    // 英语相关工作 → english XP
413	    tutoring: { skill: "english", min: 2, max: 4 },
414	    // 驾驶相关工作 → driving XP
415	    delivery_rider: { skill: "driving", min: 3, max: 6 },
416	    hospital_caregiver: { skill: "sales", min: 2, max: 5 },
417	    // 电工相关工作 → electrician XP
418	    factory_work_assembly: { skill: "electrician", min: 2, max: 4 },
419	    factory_overtime: { skill: "electrician", min: 3, max: 6 },
420	    // 焊接相关工作 → welding XP
421	    manual_labor_construction: { skill: "welding", min: 1, max: 3 },
422	  };
423	
424	  var entry = xpMap[jobId];
425	  if (!entry) return "";
426	
427	  var sk = state.skills[entry.skill];
428	  if (!sk) return "";
429	
430	  var xpGain =
431	    entry.min + Math.floor(Math.random() * (entry.max - entry.min + 1));
432	
433	  // 情绪加成技能XP（happy时1.5倍，depressed时0.3倍）
434	  var emoMod =
435	    typeof getEmotionWorkModifier === "function"
436	      ? getEmotionWorkModifier(state)
437	      : { skillXp: 1.0 };
438	  xpGain = Math.round(xpGain * emoMod.skillXp);
439	
440	  // 智力高有一定加成
441	  var intBonus = Math.floor((state.player.intelligence || 0) / 30);
442	  xpGain += intBonus;
443	
444	  // 天赋节点XP加成（P2#12 技能树系统）
445	  if (typeof getTalentNodeEffects === "function" && state.talentNodes) {
446	    var nodeEff = getTalentNodeEffects(state);
447	    var xpMultKey = entry.skill + "XpMult";
448	    if (nodeEff[xpMultKey]) {
449	      xpGain = Math.round(xpGain * nodeEff[xpMultKey]);
450	    }
451	  }
452	
453	  sk.xp = (sk.xp || 0) + xpGain;
454	
455	  // 检查升级
456	  var leveledUp = false;
457	  while (sk.xp >= (sk.level + 1) * 120 && sk.level < 100) {
458	    sk.xp -= (sk.level + 1) * 120;
459	    sk.level++;
460	    leveledUp = true;
461	    // 升级提升关联属性（微量）
462	    applySkillLevelUpBonus(entry.skill, state);
463	  }
464	
465	  var msg = "📚 " + getSkillChineseName(entry.skill) + " +" + xpGain + "XP";
466	  if (leveledUp) msg += " 🎉升级至Lv." + sk.level + "!";
467	
468	  return msg;
469	}
470	
471	/** 技能升级时提升关联属性 */
472	function applySkillLevelUpBonus(skillKey, state) {
473	  var p = state.player;
474	  var strengthSkills = ["cooking", "welding", "repair", "electrician"];
475	  var intSkills = ["coding", "english", "accounting", "management"];
476	  var agilitySkills = ["driving", "sales"];
477	
478	  if (strengthSkills.indexOf(skillKey) !== -1) {
479	    if (p.physique < 100) p.physique = Math.min(100, p.physique + 1);
480	  }
481	  if (intSkills.indexOf(skillKey) !== -1) {
482	    if (p.intelligence < 100)
483	      p.intelligence = Math.min(100, p.intelligence + 1);
484	  }
485	  if (agilitySkills.indexOf(skillKey) !== -1) {
486	    if (p.agility < 100) p.agility = Math.min(100, p.agility + 1);
487	  }
488	
489	  // 天赋节点解锁提示（P2#12）
490	  if (typeof getUnlockedTalentNodes === "function" && state.skillBranches) {
491	    var unlocked = getUnlockedTalentNodes(skillKey, state);
492	    for (var ni = 0; ni < unlocked.length; ni++) {
493	      if (typeof StateManager !== "undefined") {
494	        StateManager.addMessage(
495	          "🌟 可在技能页激活「" + unlocked[ni].name + "」天赋节点！",
496	          "hint",
497	        );
498	      }
499	    }
500	  }
501	}
502	
503	/** 行动后分发微量属性增长 */
504	function grantActionStatGain(actionId, state) {
505	  var statMap = {
506	    scavenge_trash: { physique: 0.1 },
507	    manual_labor_construction: { physique: 0.2 },
508	    factory_work_assembly: { agility: 0.2 },
509	    factory_overtime: { physique: 0.1, agility: 0.1 },
510	    barber: { agility: 0.1 },
511	    delivery_rider: { agility: 0.2 },
512	    street_performer: { mental: 0.1, fame: 1 },
513	    busking: { mental: 0.1, fame: 0.5 },
514	    tutoring: { intelligence: 0.1 },
515	    gym: { physique: 0.5 + Math.random() * 0.5 },
516	    night_school: { intelligence: 0.2 },
517	    meditation: { mental: 0.3 },
518	    diary: { mental: 0.1 },
519	    skilled_labor_construction: { physique: 0.1 },
520	  };
521	
522	  var entry = statMap[actionId];
523	  if (!entry) return "";
524	
525	  var p = state.player;
526	  var gains = [];
527	
528	  Object.keys(entry).forEach(function (key) {
529	    var gain = entry[key];
530	    if (key === "fame") {
531	      state.player.fame = (state.player.fame || 0) + gain;
532	    } else if (p[key] !== undefined && p[key] < 100) {
533	      p[key] = Math.min(100, p[key] + gain);
534	    }
535	    if (gain >= 0.5) {
536	      gains.push(getStatChineseName(key) + " +" + gain.toFixed(1));
537	    }
538	  });
539	
540	  return gains.length > 0 ? "💪 " + gains.join(", ") : "";
541	}
542	
543	/** 获取技能中文名 */
544	function getSkillChineseName(skillKey) {
545	  var names = {
546	    cooking: "烹饪",
547	    repair: "维修",
548	    coding: "编程",
549	    english: "英语",
550	    driving: "驾驶",
551	    sales: "销售",
552	    management: "管理",
553	    accounting: "会计",
554	    electrician: "电工",
555	    welding: "焊接",
556	  };
557	  return names[skillKey] || skillKey;
558	}
559	
560	/**
561	 * 摆摊客流量综合修正（位置 × 天气 × 节日 × 周末）
562	 * 供 jobs.js 的 payCalc 调用
563	 */
564	function getVendingFootfallMod(locKey, state) {
565	  // 基础客流量（来自 LOCATIONS 定义）
566	  var loc = typeof LOCATIONS !== "undefined" ? LOCATIONS[locKey] : null;
567	  var base = loc ? loc.footfall || 1.0 : 1.0;
568	
569	  // 天气修正（雨天-35%/-70%，晴天+10%）
570	  var weather = state.weather ? state.weather.current : null;
571	  if (weather === "stormy") base *= 0.3;
572	  else if (weather === "rainy") base *= 0.65;
573	  else if (weather === "snowy") base *= 0.5;
574	  else if (weather === "sunny") base *= 1.1;
575	
576	  // 节日修正（普通节日+30%；全民剁手节人流爆炸×2.5）
577	  if (typeof getCurrentFestival === "function") {
578	    var festival = getCurrentFestival(state.player.day);
579	    if (festival) {
580	      base *= festival.id === "shopping_festival" ? 2.5 : 1.3;
581	    }
582	  }
583	
584	  // 周末修正（day%7=0或6时为"周末"，客流量+20%）
585	  var dow = state.player.day % 7;
586	  if (dow === 0 || dow === 6) base *= 1.2;
587	
588	  // 新闻/政策形成的城市脉搏会改变地点客流。
589	  if (typeof getCityPulse === "function") {
590	    var pulse = getCityPulse(state);
591	    if (pulse.footfall && pulse.footfall[locKey])
592	      base *= pulse.footfall[locKey];
593	  }
594	
595	  return Math.max(0.1, base);
596	}
597	
598	/** 获取客流量星级说明（用于UI展示） */
599	function getFootfallStars(mod) {
600	  if (mod >= 2.0) return "⭐⭐⭐⭐⭐ 爆满";
601	  if (mod >= 1.5) return "⭐⭐⭐⭐ 旺盛";
602	  if (mod >= 1.0) return "⭐⭐⭐ 正常";
603	  if (mod >= 0.7) return "⭐⭐ 冷清";
604	  return "⭐ 萧条";
605	}
606	
607	/**
608	 * NPC在场加成 — 当玩家在某地点工作时，驻扎该地点且好感度足够的NPC会提供加成
609	 *
610	 * 设计参考《星露谷》：熟识的村民会帮助你更有效率地工作
611	 * 加成逻辑：NPC.presenceBonus 数组中每条规则 { minAffinity, jobs, multiplier }
612	 *   - minAffinity: 触发所需最低好感值
613	 *   - jobs: 受益的工作ID数组（null表示所有工作）
614	 *   - multiplier: 收入倍率（叠加，各NPC独立计算后相乘）
615	 *
616	 * @param {string} locKey   - 当前地点 ID
617	 * @param {string} jobId    - 正在执行的工作 ID
618	 * @param {object} state    - 游戏状态
619	 * @returns {number}        - 总收入乘数（≥1.0）
620	 */
621	function getNpcPresenceBonus(locKey, jobId, state) {
622	  if (typeof NPCS === "undefined" || !state.relationships) return 1.0;
623	  var totalMult = 1.0;
624	
625	  for (var i = 0; i < NPCS.length; i++) {
626	    var npc = NPCS[i];
627	    if (npc.location !== locKey) continue;
628	    if (!npc.presenceBonus) continue;
629	
630	    var rel = state.relationships[npc.id];
631	    var affinity = rel ? rel.affinity || 0 : 0;
632	
633	    for (var b = 0; b < npc.presenceBonus.length; b++) {
634	      var bonus = npc.presenceBonus[b];
635	      if (affinity < (bonus.minAffinity || 0)) continue;
636	      var jobMatch = !bonus.jobs || bonus.jobs.indexOf(jobId) >= 0;
637	      if (!jobMatch) continue;
638	      totalMult *= bonus.multiplier || 1.0;
639	    }
640	  }
641	
642	  return totalMult;
643	}
644	
645	/**
646	 * 获取NPC在场加成说明（用于行动提示展示）
647	 * @returns {string|null}  - 提示文字，无加成时返回 null
648	 */
649	function getNpcPresenceBonusDesc(locKey, jobId, state) {
650	  if (typeof NPCS === "undefined" || !state.relationships) return null;
651	  var lines = [];
652	
653	  for (var i = 0; i < NPCS.length; i++) {
654	    var npc = NPCS[i];
655	    if (npc.location !== locKey) continue;
656	    if (!npc.presenceBonus) continue;
657	
658	    var rel = state.relationships[npc.id];
659	    var affinity = rel ? rel.affinity || 0 : 0;
660	
661	    for (var b = 0; b < npc.presenceBonus.length; b++) {
662	      var bonus = npc.presenceBonus[b];
663	      if (affinity < (bonus.minAffinity || 0)) continue;
664	      var jobMatch = !bonus.jobs || bonus.jobs.indexOf(jobId) >= 0;
665	      if (!jobMatch) continue;
666	      var pct = Math.round((bonus.multiplier - 1) * 100);
667	      lines.push("👤 " + npc.name + "在场: +" + pct + "%");
668	    }
669	  }
670	
671	  return lines.length ? lines.join("，") : null;
672	}
673	
674	/**
675	 * NPC 好感阈值检测 — 每次好感变动后调用
676	 * 参考 Stardew Valley Heart Events：达到阈值触发一次性奖励
677	 */
678	function checkNpcAffinityRewards(npcId, state) {
679	  var npc = typeof getNpcById === "function" ? getNpcById(npcId) : null;
680	  if (!npc || !npc.affinityRewards) return;
681	  var rel = state.relationships[npcId];
682	  if (!rel) return;
683	  var affinity = rel.affinity || 0;
684	  if (!state.flags._npcRewardsClaimed) state.flags._npcRewardsClaimed = {};
685	  npc.affinityRewards.forEach(function (reward) {
686	    if (
687	      affinity >= reward.threshold &&
688	      !state.flags._npcRewardsClaimed[reward.id]
689	    ) {
690	      state.flags._npcRewardsClaimed[reward.id] = true;
691	      reward.effect(state);
692	    }
693	  });
694	}
695	
696	/** 每日财务结算 — 银行利息（含accounting技能加成） */
697	function settleDailyFinance(state) {
698	  var bal = state.resources.bankBalance || 0;
699	  if (bal <= 0) return;
700	  var accountingLvl =
701	    (state.skills.accounting && state.skills.accounting.level) || 0;
702	  var baseRate = 0.001;
703	  var bonus =
704	    typeof getBankRateBonus === "function"
705	      ? getBankRateBonus(accountingLvl)
706	      : 0;
707	  var rate = baseRate + bonus;
708	  var interest = Math.floor(bal * rate);
709	  if (interest > 0) {
710	    state.resources.bankBalance += interest;
711	    addDailyTransaction(
712	      state,
713	      "income",
714	      "bank_interest",
715	      interest,
716	      "存款利息（利率" + (rate * 100).toFixed(3) + "%）",
717	    );
718	    StateManager.addMessage(
719	      "🏦 银行利息 +¥" +
720	        interest +
721	        "（日利率" +
722	        (rate * 100).toFixed(3) +
723	        "%，存款¥" +
724	        bal.toLocaleString() +
725	        "）",
726	      "info",
727	    );
728	  }
729	}
730	
731	/**
732	 * P2.9 玩家历史→世界状态效果
733	 * 过去的道德抉择在全局留下持续性加成/惩罚。
734	 * 返回一个 mods 对象，供 main.js / events.js 读取。
735	 *
736	 * @param {object} state
737	 * @returns {{ earningsBonus: number, luckBonus: number, priceDiscount: number,
738	 *             npcAffinityBonus: number, reputationLabel: string|null }}
739	 */
740	function getHistoryModifiers(state) {
741	  var mods = {
742	    earningsBonus: 1.0,
743	    luckBonus: 0,
744	    priceDiscount: 1.0,
745	    npcAffinityBonus: 0,
746	    reputationLabel: null,
747	  };
748	  var flags = state.flags || {};
749	
750	  // 钱包善报：随机事件有隐形幸运加成
751	  if (flags._walletKarmaGood) {
752	    mods.luckBonus += 5;
753	  }
754	
755	  // 帮助工友（_helpedCoworker）：打工人认你这个人
756	  if (flags._helpedCoworker) {
757	    mods.earningsBonus *= 1.03;
758	  }
759	
760	  // 拒绝售假（_refusedFakeGoods）：诚信口碑，供货商给微小折扣
761	  if (flags._refusedFakeGoods) {
762	    mods.priceDiscount *= 0.98;
763	  }
764	
765	  // 维权成功（_foughtWageTheft）：敢维权的人在工人圈里有威望
766	  if (flags._foughtWageTheft) {
767	    mods.earningsBonus *= 1.04;
768	  }
769	
770	  // 诚信复利（_honestyCompound）：两项道德选择叠加后的综合声誉效果
771	  if (flags._honestyCompound) {
772	    mods.earningsBonus *= 1.06;
773	    mods.priceDiscount *= 0.96;
774	    mods.reputationLabel = "诚信经营者";
775	  }
776	
777	  // 劳工组织者（_laborOrganizer）：打工人主心骨，工人聚集地收入额外加成
778	  if (flags._laborNetworkGrown || flags._laborOrganizer) {
779	    mods.earningsBonus *= 1.08;
780	    mods.npcAffinityBonus += 2;
781	    mods.reputationLabel = mods.reputationLabel || "打工人主心骨";
782	  }
783	
784	  // 持证经营（_hasBusinessLicense）：合法经营声誉
785	  if (flags._hasBusinessLicense) {
786	    mods.earningsBonus *= 1.1;
787	    mods.reputationLabel = mods.reputationLabel || "持证经营者";
788	  }
789	
790	  return mods;
791	}
792	
793	// ================================================================
794	//  技能协同增益系统（P3.3）
795	//  多技能组合达到门槛时，相关工作收入持续提升
796	// ================================================================
797	
798	var SKILL_SYNERGIES = [
799	  {
800	    id: "food_merchant",
801	    label: "🍜 美食创业者",
802	    desc: "烹饪≥Lv.10 + 销售≥Lv.10：餐饮摆摊收入+15%",
803	    skills: { cooking: 10, sales: 10 },
804	    jobBonus: 0.15,
805	    jobs: ["food_stall", "street_vending_food", "restaurant_assistant"],
806	  },
807	  {
808	    id: "handyman",
809	    label: "🔧 全能工匠",
810	    desc: "维修≥Lv.10 + 电工≥Lv.10：维修/建筑工作收入+14%",
811	    skills: { repair: 10, electrician: 10 },
812	    jobBonus: 0.14,
813	    jobs: [
814	      "repair_service",
815	      "school_maintenance",
816	      "skilled_labor_construction",
817	      "premium_engineering",
818	    ],
819	  },
820	  {
821	    id: "global_dev",
822	    label: "💻 海外外包专家",
823	    desc: "编程≥Lv.15 + 英语≥Lv.15：技术/教育类工作收入+22%",
824	    skills: { coding: 15, english: 15 },
825	    jobBonus: 0.22,
826	    jobs: [
827	      "tutoring",
828	      "customer_service_tech",
829	      "junior_analyst",
830	      "content_writing",
831	    ],
832	  },
833	  {
834	    id: "delivery_ace",
835	    label: "🛵 跑单达人",
836	    desc: "销售≥Lv.8 + 驾驶≥Lv.8：配送工作收入+12%",
837	    skills: { sales: 8, driving: 8 },
838	    jobBonus: 0.12,
839	    jobs: ["delivery_rider", "package_delivery"],
840	  },
841	  {
842	    id: "biz_elite",
843	    label: "📋 商务精英",
844	    desc: "管理≥Lv.15 + 会计≥Lv.15：仓储/商务类工作收入+18%",
845	    skills: { management: 15, accounting: 15 },
846	    jobBonus: 0.18,
847	    jobs: [
848	      "warehouse_worker",
849	      "security_guard",
850	      "data_entry",
851	      "restaurant_assistant",
852	    ],
853	  },
854	  {
855	    id: "trade_expert",
856	    label: "🌐 外贸达人",
857	    desc: "英语≥Lv.12 + 销售≥Lv.12：教育/客服类工作收入+20%",
858	    skills: { english: 12, sales: 12 },
859	    jobBonus: 0.2,
860	    jobs: ["tutoring", "customer_service_tech", "content_writing"],
861	  },
862	];
863	
864	/** 返回当前激活的协同增益列表 */
865	function getSkillSynergies(state) {
866	  var active = [];
867	  for (var i = 0; i < SKILL_SYNERGIES.length; i++) {
868	    var syn = SKILL_SYNERGIES[i];
869	    var qualifies = true;
870	    for (var sk in syn.skills) {
871	      var skData = state.skills && state.skills[sk];
872	      if (!skData || skData.level < syn.skills[sk]) {
873	        qualifies = false;
874	        break;
875	      }
876	    }
877	    if (qualifies) active.push(syn);
878	  }
879	  return active;
880	}
881	
882	/** 返回特定工作的协同收入加成（叠加比例，如 0.22 = 22%） */
883	function getSkillSynergyBonus(jobId, state) {
884	  var active = getSkillSynergies(state);
885	  var total = 0;
886	  for (var i = 0; i < active.length; i++) {
887	    if (active[i].jobs.indexOf(jobId) >= 0) {
888	      total += active[i].jobBonus;
889	    }
890	  }
891	  return total;
892	}
893	
894	/** 获取属性中文名 */
895	function getStatChineseName(key) {
896	  var names = {
897	    physique: "体质",
898	    intelligence: "智力",
899	    agility: "敏捷",
900	    mental: "心智",
901	    health: "健康",
902	    hunger: "饱食度",
903	    fatigue: "疲劳",
904	    hygiene: "卫生",
905	    happiness: "心情",
906	    fame: "名气",
907	  };
908	  return names[key] || key;
909	}
910	
911	/**
912	 * 获取当前装备对特定工作的收入加成倍率
913	 * 遍历玩家已装备物品，返回 jobBonuses 中匹配的倍率
914	 * @param {string} jobId 工作ID
915	 * @param {object} state 游戏状态
916	 * @returns {number} 收入加成倍率（1.0 = 无加成）
917	 */
918	function getItemJobBonus(jobId, state) {
919	  var multiplier = 1.0;
920	  if (!state || !state.equipment || !state.inventory) return multiplier;
921	
922	  for (var slotKey in state.equipment) {
923	    var equippedId = state.equipment[slotKey];
924	    if (!equippedId) continue;
925	    var item = getItemById(equippedId);
926	    if (!item || !item.jobBonuses) continue;
927	    var bonus = item.jobBonuses[jobId];
928	    if (bonus && bonus.incomeMultiplier) {
929	      multiplier *= bonus.incomeMultiplier;
930	    }
931	  }
932	  return multiplier;
933	}
