      p[key] = Math.min(100, p[key] + gain);
    }
    if (gain >= 0.5) {
      gains.push(getStatChineseName(key) + " +" + gain.toFixed(1));
    }
  });

  return gains.length > 0 ? "💪 " + gains.join(", ") : "";
}

