1	/**
2	 * 状态互联系统 — 状态↔基础属性↔状态的深度交叉影响
3	 *
4	 * 设计参考: The Sims需求轮盘/This War of Mine状态惩罚/RimWorld意识系统/大多数生存联动
5	 *
6	 * 提供: getEffectiveStats(), getApCostMultiplier(), applyStatusInteractions(), checkExtremeConditions()
7	 */
8	
9	/** 获取经状态修正后的有效属性值（工作时、技能判定时使用） */
10	function getEffectiveStats(state) {
11	  const n = state.needs,
12	    st = state.status,
13	    p = state.player;
14	  var mult = { physique: 1.0, intelligence: 1.0, agility: 1.0, mental: 1.0 };
15	
16	  // === 饥饿影响（饿得没力气/脑子转不动） ===
17	  if (n.hunger < 30) {
18	    mult.agility *= 0.85;
19	    mult.mental *= 0.9;
20	  }
21	  if (n.hunger < 15) {
22	    mult.agility *= 0.75;
23	    mult.mental *= 0.8;
24	    mult.physique *= 0.85;
25	  }
26	  if (n.hunger < 5) {
27	    mult.agility *= 0.5;
28	    mult.mental *= 0.5;
29	    mult.physique *= 0.6;
30	  }
31	
32	  // === 疲劳影响 ===
33	  if (n.fatigue > 70) {
34	    mult.agility *= 0.85;
35	    mult.mental *= 0.9;
36	  }
37	  if (n.fatigue > 85) {
38	    mult.agility *= 0.7;
39	    mult.mental *= 0.75;
40	    mult.physique *= 0.85;
41	  }
42	  if (n.fatigue > 95) {
43	    mult.agility *= 0.5;
44	    mult.mental *= 0.5;
45	    mult.physique *= 0.7;
46	  }
47	
48	  // === 健康影响 ===
49	  if (st.health < 50) {
50	    mult.physique *= 0.85;
51	  }
52	  if (st.health < 30) {
53	    mult.physique *= 0.7;
54	    mult.agility *= 0.85;
55	  }
56	  if (st.health < 15) {
57	    mult.physique *= 0.5;
58	    mult.agility *= 0.7;
59	    mult.intelligence *= 0.85;
60	  }
61	
62	  // === 心情影响 ===
63	  if (n.happiness < 20) {
64	    mult.mental *= 0.8;
65	    mult.intelligence *= 0.9;
66	  }
67	  if (n.happiness < 10) {
68	    mult.mental *= 0.6;
69	    mult.intelligence *= 0.8;
70	  }
71	
72	  // === 生病/受伤 ===
73	  if (st.sick) {
74	    mult.physique *= 0.85;
75	    mult.agility *= 0.9;
76	    mult.mental *= 0.9;
77	  }
78	  if (st.injured) {
79	    mult.physique *= 0.75;
80	    mult.agility *= 0.7;
81	  }
82	
83	  // === 命名疾病额外属性 debuff（来自 illness.js）===
84	  if (typeof getIllnessAttrDebuffs === "function") {
85	    var ad = getIllnessAttrDebuffs(state);
86	    // ad.physique 等是"扣多少有效点数"，转为乘数：扣10点≈打0.9折
87	    if (ad.physique) mult.physique *= Math.max(0.3, 1 - ad.physique / 100);
88	    if (ad.intelligence)
89	      mult.intelligence *= Math.max(0.3, 1 - ad.intelligence / 100);
90	    if (ad.agility) mult.agility *= Math.max(0.3, 1 - ad.agility / 100);
91	    if (ad.mental) mult.mental *= Math.max(0.3, 1 - ad.mental / 100);
92	  }
93	
94	  // === 高基础属性正向反馈（好体魄抗压） ===
95	  if (p.agility > 50) mult.agility *= 1.05;
96	  if (p.mental > 50) mult.mental *= 1.05;
97	  if (p.physique > 60) mult.physique *= 1.03;
98	
99	  // === 基础属性内部互动 ===
100	  if (p.physique > 50) mult.agility *= 1.03; // 体质好→行动更敏捷
101	  if (p.mental > 50) mult.intelligence *= 1.03; // 心智强→思考更清晰
102	  if (p.intelligence > 50) mult.mental *= 1.02; // 智商高→情绪调节更好
103	
104	  // 计算有效值（保底30%）
105	  var clamp = function (v) {
106	    return Math.max(0.3, v);
107	  };
108	  return {
109	    physique: Math.round(p.physique * clamp(mult.physique)),
110	    intelligence: Math.round(p.intelligence * clamp(mult.intelligence)),
111	    agility: Math.round(p.agility * clamp(mult.agility)),
112	    mental: Math.round(p.mental * clamp(mult.mental)),
113	    multipliers: mult,
114	  };
115	}
116	
117	/** 获取当前AP消耗倍率（影响所有 consumeAP 调用的实际消耗） */
118	function getApCostMultiplier(state) {
119	  var n = state.needs,
120	    st = state.status,
121	    p = state.player;
122	  var mult = 1.0;
123	
124	  // === 负面状态增加AP消耗 ===
125	  if (n.fatigue > 70) mult += 0.2;
126	  if (n.fatigue > 85) mult += 0.25; // 累计+0.45
127	  if (n.fatigue > 95) mult += 0.35; // 累计+0.8
128	
129	  if (n.hunger < 20) mult += 0.3;
130	  if (n.hunger < 10) mult += 0.2; // 累计+0.5
131	
132	  if (st.sick) mult += 0.5;
133	  if (st.injured) mult += 0.3;
134	
135	  if (n.happiness < 15) mult += 0.2;
136	
137	  // === 命名疾病额外 AP 倍率（来自 illness.js）===
138	  if (typeof getIllnessAttrDebuffs === "function") {
139	    var ad = getIllnessAttrDebuffs(state);
140	    if (ad.apMult) mult += ad.apMult;
141	  }
142	
143	  // === 天气影响AP ===
144	  if (state.weather) {
145	    var w = state.weather.current;
146	    if (w === "heatwave" || w === "coldwave") mult += 0.2;
147	    if (w === "storm" || w === "snow") mult += 0.15;
148	  }
149	
150	  // === 高敏捷减免（身体灵活→做事高效） ===
151	  if (p.agility > 50) mult -= 0.1;
152	  if (p.agility > 75) mult -= 0.1; // 累计-0.2
153	
154	  // === 保底：AP消耗至少为原始的50%，最多为250% ===
155	  return Math.max(0.5, Math.min(2.5, mult));
156	}
157	
158	/** 每日结算时施加状态→状态的交叉影响（在applyNeedsDecay之后调用） */
159	function applyStatusInteractions(state) {
160	  var n = state.needs,
161	    st = state.status,
162	    p = state.player;
163	
164	  // --- 饥饿加速疲劳（没吃饭→没力气→更容易累） ---
165	  if (n.hunger < 30) n.fatigue = Math.min(100, n.fatigue + 5);
166	  if (n.hunger < 15) n.fatigue = Math.min(100, n.fatigue + 8);
167	
168	  // --- 饥饿→心情下降（饿肚子不开心） ---
169	  if (n.hunger < 20) n.happiness = Math.max(0, n.happiness - 5);
170	
171	  // --- 疲劳→心情下降（累了心情自然差） ---
172	  if (n.fatigue > 70) n.happiness = Math.max(0, n.happiness - 3);
173	  if (n.fatigue > 85) n.happiness = Math.max(0, n.happiness - 5);
174	
175	  // --- 疲劳→懒得洗漱 ---
176	  if (n.fatigue > 85) n.hygiene = Math.max(0, n.hygiene - 3);
177	
178	  // --- 卫生差→心情下降 ---
179	  if (n.hygiene < 20) n.happiness = Math.max(0, n.happiness - 3);
180	  if (n.hygiene < 10) n.happiness = Math.max(0, n.happiness - 5);
181	
182	  // --- 心情好→缓解疲劳（心情愉快精力恢复快） ---
183	  if (n.happiness > 70) n.fatigue = Math.max(0, n.fatigue - 3);
184	  if (n.happiness > 85) n.fatigue = Math.max(0, n.fatigue - 5);
185	
186	  // --- 心情差→疲劳恢复减半（存入临时标记，endDay睡眠恢复时使用） ---
187	  state._fatigueRecoveryPenalty = n.happiness < 20 ? 0.5 : 1.0;
188	
189	  // --- 健康差→疲劳增长（身体不好容易累） ---
190	  if (st.health < 50) n.fatigue = Math.min(100, n.fatigue + 3);
191	  if (st.health < 30) n.fatigue = Math.min(100, n.fatigue + 5);
192	
193	  // --- 生病/受伤的全面影响 ---
194	  if (st.sick) {
195	    n.fatigue = Math.min(100, n.fatigue + 8);
196	    n.happiness = Math.max(0, n.happiness - 5);
197	    n.hygiene = Math.max(0, n.hygiene - 2);
198	  }
199	  if (st.injured) {
200	    n.fatigue = Math.min(100, n.fatigue + 5);
201	    n.happiness = Math.max(0, n.happiness - 3);
202	  }
