822	/** 随机触发一个道德事件（在consumeAP中调用）。返回true表示触发了 */
823	function triggerMoralEvent(state) {
824	  // 每日最多一次
825	  var todayActions = (state.flags.moral.actions || []).filter(function (a) {
826	    return a.day === state.player.day;
827	  });
828	  if (todayActions.length > 0) return false;
829	
830	  var hasWalletAction = (state.flags.moral.actions || []).some(function (a) {
831	    return a.id === "found_wallet";
832	  });
833	
834	  var eligible = [];
835	  for (var i = 0; i < MORAL_EVENTS.length; i++) {
836	    var evt = MORAL_EVENTS[i];
837	    if (evt.minDay && state.player.day < evt.minDay) continue;
838	    if (evt.condition && !evt.condition(state)) continue;
839	    if (
840	      (state.flags.moral.actions || []).some(function (a) {
841	        return a.id === evt.id;
842	      })
843	    )
844	      continue;
845	    if (
846	      hasWalletAction &&
847	      (evt.id === "found_phone" || evt.id === "found_wallet")
848	    )
849	      continue;
850	    eligible.push(evt);
851	  }
852	  if (eligible.length === 0) return false;
853	
854	  var evt = eligible[Math.floor(Math.random() * eligible.length)];
855	  if (Math.random() > evt.dailyChance) return false;
856	
857	  // 构建选择按钮
858	  var buttons = evt.choices.map(function (choice) {
859	    return {
860	      text: choice.text,
861	      cls: "btn-primary",
862	      callback: function () {
863	        var s = StateManager.getState();
864	        if (!s.flags.moral.actions) s.flags.moral.actions = [];
865	        s.flags.moral.actions.push({
866	          id: evt.id,
867	          choice: choice.flag,
868	          score: choice.score,
869	          day: s.player.day,
870	        });
871	        s.flags.moral.score = Math.max(
872	          -100,
873	          Math.min(100, (s.flags.moral.score || 0) + choice.score),
874	        );
875	        if (choice.immediate) choice.immediate(s);
876	        var consequenceDef = MORAL_CONSEQUENCES[choice.flag];
877	        if (consequenceDef) {
878	          if (!s.flags.moral.pendingConsequences)
879	            s.flags.moral.pendingConsequences = [];
880	          var delay = Random.int(
881	            consequenceDef.delay[0],
882	            consequenceDef.delay[1],
883	          );
884	          s.flags.moral.pendingConsequences.push({
885	            eventId: consequenceDef.id,
886	            actionId: choice.flag,
887	            dueDay: s.player.day + delay,
888	          });
889	        }
890	        renderAll();
891	      },
892	    };
893	  });
894	
895	  showModal({
896	    title: evt.title,
897	    body: '<p style="line-height:1.7;">' + evt.desc + "</p>",
898	    buttons: buttons,
899	  });
900	  return true;
901	}
902	
903	/** 每日检查并触发待处理的道德后果（在 daily_pipeline 中调用） */
904	function checkMoralConsequences(state) {
905	  var pending = state.flags.moral.pendingConsequences;
906	  if (!pending || pending.length === 0) return;
907	
908	  var due = [],
909	    remaining = [];
910	  for (var i = 0; i < pending.length; i++) {
911	    if (pending[i].dueDay <= state.player.day) due.push(pending[i]);
912	    else remaining.push(pending[i]);
913	  }
914	  state.flags.moral.pendingConsequences = remaining;
915	
916	  for (var di = 0; di < due.length; di++) {
917	    var con = due[di];
918	    var action = (state.flags.moral.actions || []).find(function (a) {
919	      return a.choice === con.actionId;
920	    });
921	    if (!action) continue;
922	    var consequenceDef = MORAL_CONSEQUENCES[con.actionId];
923	    if (!consequenceDef) continue;
924	
925	    var descText =
926	      typeof consequenceDef.desc === "function"
927	        ? consequenceDef.desc(state)
928	        : consequenceDef.desc;
929	    showModal({
930	      title: consequenceDef.title,
931	      body: '<p style="line-height:1.7;">' + descText + "</p>",
932	      buttons: [
933	        {
934	          text: "知道了",
935	          cls: "btn-primary",
936	          callback: function () {
937	            var s2 = StateManager.getState();
938	            consequenceDef.apply(s2);
939	            renderAll();
940	          },
941	        },
942	      ],
943	    });
944	  }
945	}
946	
947	function getMoralLevelName(score) {
948	  if (score >= 80) return "圣贤";
949	  if (score >= 50) return "善良";
950	  if (score >= 20) return "正直";
951	  if (score >= -10) return "普通人";
952	  if (score >= -40) return "自私";
953	  if (score >= -70) return "冷漠";
954	  return "堕入黑暗";
955	}
956	
957	function getMoralEmoji(score) {
958	  if (score >= 50) return "😇";
959	  if (score >= 20) return "👍";
960	  if (score >= -10) return "😐";
961	  if (score >= -40) return "😒";
962	  return "👿";
963	}
